#ifndef TRAJECTORY_GENERATOR_HPP
#define TRAJECTORY_GENERATOR_HPP

#include "dls2/msg_wrappers/wrapper.hpp"
#include "dls_messages/dds/trajectory_generator.h"
#include "dls2/msg_wrappers/pose.hpp"
#include "dls2/msg_wrappers/screw.hpp"
#include <robotlib/robot_base.hpp>

/// A structure containing the data streams that make up the signal at the
/// current time generated by a given gait generator
namespace dls
{
	struct TrajectoryGenerator : public Wrapper<TrajectoryGeneratorMsg>
	{
		TrajectoryGenerator(const std::shared_ptr<robotlib::RobotBase> robot);
		TrajectoryGenerator(TrajectoryGenerator& trajectory_generator);
		TrajectoryGenerator() = delete;
		virtual ~TrajectoryGenerator();
		
		operator TrajectoryGeneratorMsg() const override;
		TrajectoryGenerator& operator= (const TrajectoryGeneratorMsg& trajectory_generator_msg) override;
		TrajectoryGenerator& operator=(const TrajectoryGenerator& trajectory_generator);

		std::string frame_id_{};
		uint32_t sequence_id_{};
		double timestamp_{};

		Pose desired_com_pose_world_;            ///< The desired pose of the center of mass frame
		Screw desired_com_velocity_world_;        ///< The desired velocity of the center of mass frame
		Screw desired_com_acceleration_world_;    ///< The desired accleration of the center of mass frame

		/// Desired joint position, velocity and acceleration.
		/// The effort field corresponds to the desired feed-forward torques
		robotlib::JointState desired_joints_position_;
		robotlib::JointState desired_joints_velocity_;
		robotlib::JointState desired_joints_acceleration_;
		robotlib::JointState desired_joints_effort_;

		Eigen::Matrix<double, 6, 1> desired_wrench_;

		robotlib::LegDataMap<bool> stance_legs_;

		robotlib::LegDataMap<Eigen::Vector3d> nominal_touch_down_;
        robotlib::LegDataMap<Eigen::Vector3d> touch_down_;
        robotlib::LegDataMap<double> swing_period_;

        robotlib::LegDataMap<double> normal_force_max_;
        robotlib::LegDataMap<double> normal_force_min_;
	};
} // namespace dls
#endif